style.css:
body {
    margin: 0;
    padding: 0;
    overflow: hidden;
}

body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: url('https://drive.google.com/file/d/1gSAT7iipNs4zvGiJltGyhwJ7h1767FUr/view?usp=sharing') no-repeat center center fixed;
    background-size: cover;
    z-index: -1;
    animation: playVideo 0.1s infinite;
}

@keyframes playVideo {
    0% { background-position: 0% 0%; }
    100% { background-position: 100% 100%; }
}
